extras.md:
- **Flour & water** come from a standard baker's-percentage relationship: total dough weight = flour + water, where water is expressed as a hydration % of the flour. So `flour = total dough weight ÷ (1 + hydration%)`, and `water = flour × hydration%`.
- **Salt** is just a percentage of the flour weight (typically 2–2.5%).
- **Yeast** is the interesting part — it's not a fixed percentage, but an estimate that shrinks as proof time and temperature increase (since yeast has more time/warmth to work):
  - It starts from a base amount that scales with (but slightly less than linearly to) the flour weight.
  - That base is reduced exponentially for every degree above 13°C, and separately reduced exponentially for every hour above 8h of proof — longer/warmer proofs need less yeast.
  - A **long proof (24–48h)** gets an extra reduction proportional to the square of `(proof hours ÷ 24)` — i.e., yeast drops off much faster than time increases.
  - A **short proof (1–7h)** uses a steeper time-decay curve instead (needs more yeast per hour saved than the regular range).
  - A **cold (fridge) proof** ignores the temperature curve entirely and instead applies a small fixed multiplier, since the fridge holds a near-constant low temperature.
  - The yeast type then scales the result: instant dried is the baseline, active dried needs ~1.25×, fresh (cake) yeast needs ~3×.

Adjust any field below and the recipe updates automatically.

```dataviewjs
const state = {
	pizzaType: "Neapolitan",
	pizzaSize: "Regular",
	proofType: "Room",
	proofLength: "Regular",
	numPizzas: 1,
	doughWeight: 260,
	hydration: 58,
	salt: 2.2,
	proofTime: 24,
	proofTemp: 20,
	yeastType: "instantYeast",
};

const HYDRATION_RANGES = {
	"Neapolitan": { min: 55, max: 62, default: 58 },
	"New York":   { min: 60, max: 70, default: 60 },
	"Detroit":    { min: 70, max: 80, default: 70 },
};

const WEIGHT_RANGES = {
	"Regular": { min: 200, max: 280, step: 10, default: 260 },
	"Large":   { min: 290, max: 400, step: 10, default: 320 },
};

const PROOF_TIME_RANGES = {
	"Short":   { min: 1,  max: 7,  default: 4 },
	"Regular": { min: 8,  max: 24, default: 24 },
	"Long":    { min: 25, max: 48, default: 36 },
};

function range(min, max, step = 1) {
	const out = [];
	for (let v = min; v <= max; v += step) out.push(Math.round(v * 100) / 100);
	return out;
}

function fillSelect(select, values, selected, formatLabel) {
	select.innerHTML = "";
	for (const v of values) {
		const opt = document.createElement("option");
		opt.value = v;
		opt.textContent = formatLabel ? formatLabel(v) : v;
		if (v == selected) opt.selected = true;
		select.appendChild(opt);
	}
}

// --- Yeast model -----------------------------------------------------
function calcYeast(flourRaw, proofTemp, proofTime, proofType, proofLength, yeastType) {
	const tempDiff = proofTemp - 13;
	const timeDiff = proofTime - 8;
	const yeastBase = flourRaw / (91 + Math.sqrt(flourRaw));

	const applyType = (val, instantMultiplier = 1) => {
		if (yeastType === "activeYeast") return val * 1.25;
		if (yeastType === "freshYeast") return val * 3;
		return val * instantMultiplier;
	};

	// Regular-length baseline (8-24h curve)
	const yeastByTempRegular = yeastBase * Math.pow(0.81, tempDiff);
	const yeastByTimeRegular = yeastByTempRegular * Math.pow(0.899, timeDiff);
	let result = applyType(yeastByTimeRegular);

	if (proofLength === "Short") {
		const yeastByTimeShort = yeastByTempRegular * Math.pow(0.69, timeDiff);
		result = applyType(yeastByTimeShort, 0.75);
	} else if (proofLength === "Long") {
		const longFactor = Math.pow(proofTime / 24, 2);
		result = result * longFactor;
	}

	if (proofType === "Cold") {
		const yeastByTempCold = yeastBase * 0.23;
		const yeastByTimeCold = yeastByTempCold * Math.pow(0.98, timeDiff);
		result = applyType(yeastByTimeCold);
	}

	return Math.round((result + Number.EPSILON) * 10000) / 10000;
}

function calculate() {
	const totalDough = state.numPizzas * state.doughWeight;
	const hydrationDecimal = state.hydration / 100;
	const flourRaw = totalDough / (1 + hydrationDecimal);
	const flour = Math.round(flourRaw);
	const water = Math.round(flour * hydrationDecimal);
	const salt = Math.round(flour * (state.salt / 100));
	const yeast = calcYeast(flourRaw, state.proofTemp, state.proofTime, state.proofType, state.proofLength, state.yeastType);

	return { flour, water, salt, yeast, totalDough };
}

// --- UI ---------------------------------------------------------------
const container = document.createElement("div");
container.style.display = "grid";
container.style.gridTemplateColumns = "repeat(auto-fit, minmax(180px, 1fr))";
container.style.gap = "0.75em";
container.style.marginBottom = "1em";

function field(labelText) {
	const box = document.createElement("div");
	const label = document.createElement("label");
	label.textContent = labelText;
	label.style.display = "block";
	label.style.fontSize = "0.85em";
	label.style.marginBottom = "0.25em";
	label.style.opacity = "0.8";
	const select = document.createElement("select");
	select.style.width = "100%";
	box.appendChild(label);
	box.appendChild(select);
	container.appendChild(box);
	return select;
}

const typeSelect = field("Type of Pizza");
fillSelect(typeSelect, ["Neapolitan", "New York", "Detroit"], state.pizzaType);

const sizeSelect = field("Size of Pizza");
fillSelect(sizeSelect, ["Regular", "Large"], state.pizzaSize);

const proofTypeSelect = field("Type of Proof");
fillSelect(proofTypeSelect, ["Room", "Cold"], state.proofType, v => v === "Room" ? "Room Temperature" : "Cold Proof (Fridge)");

const proofLengthSelect = field("Length of Proof");

const numSelect = field("Number of Pizzas");
fillSelect(numSelect, range(1, 20), state.numPizzas);

const weightSelect = field("Dough Weight (g)");

const hydrationSelect = field("Hydration - Water (%)");

const saltSelect = field("Salt Content (%)");
fillSelect(saltSelect, range(2.0, 2.5, 0.1), state.salt);

const proofTimeSelect = field("Proof Time (hours)");

const proofTempSelect = field("Proof Temp (C/F)");

const yeastTypeSelect = field("Yeast Type");
fillSelect(yeastTypeSelect, ["instantYeast", "activeYeast", "freshYeast"], state.yeastType, v => ({
	instantYeast: "Instant Dried",
	activeYeast: "Active Dried",
	freshYeast: "Fresh Yeast",
}[v]));

function refreshHydration() {
	const r = HYDRATION_RANGES[state.pizzaType];
	if (state.hydration < r.min || state.hydration > r.max) {
		state.hydration = r.default;
	}
	fillSelect(hydrationSelect, range(r.min, r.max), state.hydration);
}

function refreshWeight() {
	const r = WEIGHT_RANGES[state.pizzaSize];
	if (state.doughWeight < r.min || state.doughWeight > r.max) state.doughWeight = r.default;
	fillSelect(weightSelect, range(r.min, r.max, r.step), state.doughWeight);
}

function refreshProofLength() {
	const options = state.proofType === "Cold" ? ["Long"] : ["Short", "Regular", "Long"];
	if (!options.includes(state.proofLength)) state.proofLength = state.proofType === "Cold" ? "Long" : "Regular";
	fillSelect(proofLengthSelect, options, state.proofLength, v => {
		const r = PROOF_TIME_RANGES[v];
		return `${v} (${r.min}-${r.max} hours)`;
	});
	proofLengthSelect.disabled = state.proofType === "Cold";
}

function refreshProofTime() {
	const r = PROOF_TIME_RANGES[state.proofLength];
	state.proofTime = r.default;
	fillSelect(proofTimeSelect, range(r.min, r.max), state.proofTime);
}

function refreshProofTemp() {
	if (state.proofType === "Cold") {
		fillSelect(proofTempSelect, [5], 5, () => "4-7C / 40-45F");
		state.proofTemp = 5;
		proofTempSelect.disabled = true;
	} else {
		const vals = range(13, 33);
		fillSelect(proofTempSelect, vals, state.proofTemp === 5 ? 20 : state.proofTemp, c => `${c}C / ${Math.round(c * 9 / 5 + 32)}F`);
		if (state.proofTemp === 5) state.proofTemp = 20;
		proofTempSelect.disabled = false;
	}
}

const resultsEl = document.createElement("div");
resultsEl.style.padding = "0.75em 1em";
resultsEl.style.border = "1px solid var(--background-modifier-border)";
resultsEl.style.borderRadius = "6px";
resultsEl.style.marginTop = "0.5em";

function render() {
	const { flour, water, salt, yeast, totalDough } = calculate();
	const yeastPct = flour ? Math.round((yeast / flour) * 10000) / 100 : 0;
	resultsEl.innerHTML = "";
	const title = document.createElement("strong");
	title.textContent = `Your Recipe (${state.numPizzas} x ${state.doughWeight}g = ${totalDough}g total dough)`;
	resultsEl.appendChild(title);
	const list = document.createElement("ul");
	list.style.margin = "0.5em 0 0 0";
	[
		["Flour", `${flour} g`],
		["Water", `${water} g (${state.hydration}% hydration)`],
		["Salt", `${salt} g (${state.salt}%)`],
		["Yeast", `${yeast} g (${yeastPct}%, ${state.yeastType})`],
	].forEach(([k, v]) => {
		const li = document.createElement("li");
		li.textContent = `${k}: ${v}`;
		list.appendChild(li);
	});
	resultsEl.appendChild(list);

	if (state.numPizzas > 1) {
		const perBall = document.createElement("div");
		perBall.style.marginTop = "0.5em";
		perBall.style.opacity = "0.8";
		perBall.style.fontSize = "0.9em";
		perBall.textContent = `Per dough ball: ${Math.round(flour / state.numPizzas)}g flour, ${Math.round(water / state.numPizzas)}g water, ${Math.round(salt / state.numPizzas)}g salt, ${Math.round((yeast / state.numPizzas) * 10000) / 10000}g yeast`;
		resultsEl.appendChild(perBall);
	}
}

function bind(select, key, isFloat = false) {
	select.addEventListener("change", () => {
		state[key] = isFloat ? parseFloat(select.value) : (isNaN(Number(select.value)) ? select.value : Number(select.value));
		onDependencyChange(key);
		render();
	});
}

function onDependencyChange(key) {
	if (key === "pizzaType") refreshHydration();
	if (key === "pizzaSize") refreshWeight();
	if (key === "proofType") { refreshProofLength(); refreshProofTemp(); refreshProofTime(); }
	if (key === "proofLength") refreshProofTime();
}

bind(typeSelect, "pizzaType");
bind(sizeSelect, "pizzaSize");
bind(proofTypeSelect, "proofType");
bind(proofLengthSelect, "proofLength");
bind(numSelect, "numPizzas");
bind(weightSelect, "doughWeight");
bind(hydrationSelect, "hydration");
bind(saltSelect, "salt", true);
bind(proofTimeSelect, "proofTime");
bind(proofTempSelect, "proofTemp");
bind(yeastTypeSelect, "yeastType");

// Initial population of dependent fields
refreshHydration();
refreshWeight();
refreshProofLength();
refreshProofTemp();
refreshProofTime();
render();

dv.container.appendChild(container);
dv.container.appendChild(resultsEl);
```
